-- 升级改为选包 SCP 覆盖；启停收窄进程匹配；安装增加 SHA 校验与临时包清理

UPDATE job_definitions
SET description = '监控纳管：SCP 下发新包，保留现有 conf，替换二进制并重启',
    script_content = '#!/bin/bash\nset -euo pipefail\n: \"${ZBX_PACKAGE_FILE:?缺少 ZBX_PACKAGE_FILE}\"\nINSTALL_PATH=\"${ZBX_INSTALL_PATH:-/opt/ITM/IIM/zabbix_agentd}\"\nCONF=\"$INSTALL_PATH/etc/zabbix_agentd.conf\"\nif [ ! -d \"$INSTALL_PATH\" ]; then echo \"安装目录不存在: $INSTALL_PATH\" >&2; exit 1; fi\nif [ ! -f \"$CONF\" ]; then echo \"缺少 conf: $CONF\" >&2; exit 1; fi\nif [ -n \"${ZBX_PACKAGE_SHA256:-}\" ]; then\n  got=$(sha256sum \"$ZBX_PACKAGE_FILE\" | awk ''{print $1}'')\n  if [ \"$got\" != \"$ZBX_PACKAGE_SHA256\" ]; then echo \"包校验失败\" >&2; exit 1; fi\nfi\nTMPDIR=$(mktemp -d)\ncleanup() { rm -rf \"$TMPDIR\"; rm -f \"$ZBX_PACKAGE_FILE\" 2>/dev/null || true; }\ntrap cleanup EXIT\ncase \"$ZBX_PACKAGE_FILE\" in\n  *.tar.gz|*.tgz) tar -xzf \"$ZBX_PACKAGE_FILE\" -C \"$TMPDIR\" ;;\n  *.tar) tar -xf \"$ZBX_PACKAGE_FILE\" -C \"$TMPDIR\" ;;\n  *.zip) unzip -q \"$ZBX_PACKAGE_FILE\" -d \"$TMPDIR\" ;;\n  *) echo \"不支持的包格式\" >&2; exit 1 ;;\nesac\nSRC=\"\"\nif [ -d \"$TMPDIR/zabbix_agentd\" ]; then SRC=\"$TMPDIR/zabbix_agentd\"\nelif [ -d \"$TMPDIR/IIM/zabbix_agentd\" ]; then SRC=\"$TMPDIR/IIM/zabbix_agentd\"\nelif [ -d \"$TMPDIR/sbin\" ]; then SRC=\"$TMPDIR\"\nelse SRC=$(find \"$TMPDIR\" -type d -name zabbix_agentd 2>/dev/null | head -1 || true); fi\nif [ -z \"$SRC\" ]; then echo \"包内未找到 zabbix_agentd\" >&2; exit 1; fi\npkill -f \"$CONF\" 2>/dev/null || true\nsleep 1\ncp -a \"$SRC/sbin\"/. \"$INSTALL_PATH/sbin\"/ 2>/dev/null || true\ncp -a \"$SRC/bin\"/. \"$INSTALL_PATH/bin\"/ 2>/dev/null || true\ncp -a \"$SRC/lib\"/. \"$INSTALL_PATH/lib\"/ 2>/dev/null || true\nchmod +x \"$INSTALL_PATH/sbin\"/* 2>/dev/null || true\nBIN=$(find \"$INSTALL_PATH/sbin\" -type f \\( -name zabbix_agentd -o -name zabbix_agent2 \\) 2>/dev/null | head -1)\nif [ -z \"$BIN\" ]; then echo \"未找到 agent 二进制\" >&2; exit 1; fi\n\"$BIN\" -c \"$CONF\"\nsleep 1\npgrep -f \"$CONF\" >/dev/null\necho upgraded\n',
    timeout_secs = 900
WHERE name = 'Zabbix Agent 升级';

UPDATE job_definitions
SET description = '监控纳管：回滚到指定包（保留 conf）',
    script_content = '#!/bin/bash\nset -euo pipefail\n: \"${ZBX_PACKAGE_FILE:?缺少 ZBX_PACKAGE_FILE}\"\nINSTALL_PATH=\"${ZBX_INSTALL_PATH:-/opt/ITM/IIM/zabbix_agentd}\"\nCONF=\"$INSTALL_PATH/etc/zabbix_agentd.conf\"\nif [ ! -f \"$CONF\" ]; then echo \"缺少 conf: $CONF\" >&2; exit 1; fi\nif [ -n \"${ZBX_PACKAGE_SHA256:-}\" ]; then\n  got=$(sha256sum \"$ZBX_PACKAGE_FILE\" | awk ''{print $1}'')\n  if [ \"$got\" != \"$ZBX_PACKAGE_SHA256\" ]; then echo \"包校验失败\" >&2; exit 1; fi\nfi\nTMPDIR=$(mktemp -d)\ncleanup() { rm -rf \"$TMPDIR\"; rm -f \"$ZBX_PACKAGE_FILE\" 2>/dev/null || true; }\ntrap cleanup EXIT\ncase \"$ZBX_PACKAGE_FILE\" in\n  *.tar.gz|*.tgz) tar -xzf \"$ZBX_PACKAGE_FILE\" -C \"$TMPDIR\" ;;\n  *.tar) tar -xf \"$ZBX_PACKAGE_FILE\" -C \"$TMPDIR\" ;;\n  *.zip) unzip -q \"$ZBX_PACKAGE_FILE\" -d \"$TMPDIR\" ;;\n  *) echo \"不支持的包格式\" >&2; exit 1 ;;\nesac\nSRC=\"\"\nif [ -d \"$TMPDIR/zabbix_agentd\" ]; then SRC=\"$TMPDIR/zabbix_agentd\"\nelif [ -d \"$TMPDIR/IIM/zabbix_agentd\" ]; then SRC=\"$TMPDIR/IIM/zabbix_agentd\"\nelif [ -d \"$TMPDIR/sbin\" ]; then SRC=\"$TMPDIR\"\nelse SRC=$(find \"$TMPDIR\" -type d -name zabbix_agentd 2>/dev/null | head -1 || true); fi\nif [ -z \"$SRC\" ]; then echo \"包内未找到 zabbix_agentd\" >&2; exit 1; fi\npkill -f \"$CONF\" 2>/dev/null || true\nsleep 1\ncp -a \"$SRC/sbin\"/. \"$INSTALL_PATH/sbin\"/ 2>/dev/null || true\ncp -a \"$SRC/bin\"/. \"$INSTALL_PATH/bin\"/ 2>/dev/null || true\nchmod +x \"$INSTALL_PATH/sbin\"/* 2>/dev/null || true\nBIN=$(find \"$INSTALL_PATH/sbin\" -type f \\( -name zabbix_agentd -o -name zabbix_agent2 \\) 2>/dev/null | head -1)\n\"$BIN\" -c \"$CONF\"\nsleep 1\npgrep -f \"$CONF\" >/dev/null\necho rolled_back\n',
    timeout_secs = 900
WHERE name = 'Zabbix Agent 回滚';

UPDATE job_definitions
SET script_content = '#!/bin/bash\nset -euo pipefail\ntrap ''echo \"安装失败：请检查包是否下发、安装目录权限、conf 模板后缀是否存在\" >&2'' ERR\n: \"${ZBX_PACKAGE_FILE:?缺少 ZBX_PACKAGE_FILE（包未下发）}\"\n: \"${ZBX_HOSTNAME:?缺少 ZBX_HOSTNAME}\"\nINSTALL_PATH=\"${ZBX_INSTALL_PATH:-/opt/ITM/IIM/zabbix_agentd}\"\nCONF_SUFFIX=\"${ZBX_CONF_SUFFIX:-}\"\nSERVER=\"${ZBX_SERVER:-}\"\nSERVER_ACTIVE=\"${ZBX_SERVER_ACTIVE:-$ZBX_SERVER}\"\nif [ ! -f \"$ZBX_PACKAGE_FILE\" ]; then\n  echo \"包文件不存在: $ZBX_PACKAGE_FILE\" >&2\n  exit 1\nfi\nif [ -n \"${ZBX_PACKAGE_SHA256:-}\" ]; then\n  got=$(sha256sum \"$ZBX_PACKAGE_FILE\" | awk ''{print $1}'')\n  if [ \"$got\" != \"$ZBX_PACKAGE_SHA256\" ]; then\n    echo \"包 SHA256 校验失败 expect=$ZBX_PACKAGE_SHA256 got=$got\" >&2\n    exit 1\n  fi\nfi\nmkdir -p \"$(dirname \"$INSTALL_PATH\")\"\nTMPDIR=$(mktemp -d)\ncleanup() { rm -rf \"$TMPDIR\"; rm -f \"$ZBX_PACKAGE_FILE\" 2>/dev/null || true; }\ntrap cleanup EXIT\ncase \"$ZBX_PACKAGE_FILE\" in\n  *.tar.gz|*.tgz) tar -xzf \"$ZBX_PACKAGE_FILE\" -C \"$TMPDIR\" ;;\n  *.tar) tar -xf \"$ZBX_PACKAGE_FILE\" -C \"$TMPDIR\" ;;\n  *.zip) command -v unzip >/dev/null || { echo \"需要 unzip\" >&2; exit 1; }; unzip -q \"$ZBX_PACKAGE_FILE\" -d \"$TMPDIR\" ;;\n  *) echo \"不支持的包格式\" >&2; exit 1 ;;\nesac\nSRC=\"\"\nif [ -d \"$TMPDIR/zabbix_agentd\" ]; then SRC=\"$TMPDIR/zabbix_agentd\"\nelif [ -d \"$TMPDIR/IIM/zabbix_agentd\" ]; then SRC=\"$TMPDIR/IIM/zabbix_agentd\"\nelif [ -d \"$TMPDIR/sbin\" ] && [ -d \"$TMPDIR/etc\" ]; then SRC=\"$TMPDIR\"\nelse\n  SRC=$(find \"$TMPDIR\" -type d -name zabbix_agentd 2>/dev/null | head -1 || true)\nfi\nif [ -z \"$SRC\" ] || [ ! -d \"$SRC\" ]; then\n  echo \"压缩包内未找到 zabbix_agentd 目录\" >&2\n  exit 1\nfi\nrm -rf \"$INSTALL_PATH\"\nmkdir -p \"$INSTALL_PATH\"\ncp -a \"$SRC\"/. \"$INSTALL_PATH\"/\nCONF=\"$INSTALL_PATH/etc/zabbix_agentd.conf\"\nmkdir -p \"$INSTALL_PATH/etc\" \"$INSTALL_PATH/log\" \"$INSTALL_PATH/pid\" \"$INSTALL_PATH/sbin\"\nif [ -n \"$CONF_SUFFIX\" ]; then\n  SRC_CONF=\"$INSTALL_PATH/etc/zabbix_agentd.conf_${CONF_SUFFIX}\"\n  if [ ! -f \"$SRC_CONF\" ]; then\n    echo \"conf 模板不存在: $SRC_CONF\" >&2\n    exit 1\n  fi\n  cp -f \"$SRC_CONF\" \"$CONF\"\nfi\nif [ ! -f \"$CONF\" ]; then\n  echo \"缺少配置文件 $CONF\" >&2\n  exit 1\nfi\nHOST_IP=$(hostname -I 2>/dev/null | awk ''{print $1}'')\nif [ -z \"$HOST_IP\" ]; then\n  HOST_IP=$(ip -4 addr show 2>/dev/null | awk ''/inet /{print $2}'' | cut -d/ -f1 | grep -v ''^127\\.'' | head -1 || true)\nfi\nif [ -n \"$HOST_IP\" ]; then\n  sed -i \"s/templateIP/${HOST_IP}/g\" \"$CONF\"\nfi\nset_kv() {\n  local key=\"$1\" val=\"$2\"\n  if grep -q \"^${key}=\" \"$CONF\"; then\n    sed -i \"s|^${key}=.*|${key}=${val}|\" \"$CONF\"\n  else\n    echo \"${key}=${val}\" >> \"$CONF\"\n  fi\n}\nif [ -n \"$SERVER\" ]; then set_kv Server \"$SERVER\"; fi\nif [ -n \"$SERVER_ACTIVE\" ]; then set_kv ServerActive \"$SERVER_ACTIVE\"; fi\nset_kv Hostname \"$ZBX_HOSTNAME\"\nset_kv PidFile \"$INSTALL_PATH/pid/zabbix_agentd.pid\"\nset_kv LogFile \"$INSTALL_PATH/log/zabbix_agentd.log\"\nBIN=\"\"\nfor c in zabbix_agentd zabbix_agent2; do\n  if [ -x \"$INSTALL_PATH/sbin/$c\" ]; then BIN=\"$INSTALL_PATH/sbin/$c\"; break; fi\ndone\nif [ -z \"$BIN\" ]; then\n  BIN=$(find \"$INSTALL_PATH/sbin\" -type f -name ''zabbix_agent*'' 2>/dev/null | head -1 || true)\nfi\nif [ -z \"$BIN\" ] || [ ! -x \"$BIN\" ]; then\n  echo \"未找到可执行的 zabbix_agent 二进制\" >&2\n  exit 1\nfi\nchmod +x \"$BIN\" \"$INSTALL_PATH/sbin\"/*.sh 2>/dev/null || true\npkill -f \"$CONF\" 2>/dev/null || true\nsleep 1\n\"$BIN\" -c \"$CONF\"\nsleep 1\nif ! pgrep -f \"$CONF\" >/dev/null; then\n  echo \"Agent 启动失败\" >&2\n  exit 1\nfi\necho \"installed=$INSTALL_PATH bin=$BIN conf_suffix=${CONF_SUFFIX:-none}\"\n'
WHERE name = 'Zabbix Agent 安装';

UPDATE job_definitions
SET script_content = '#!/bin/bash\nset -euo pipefail\nINSTALL_PATH=\"${ZBX_INSTALL_PATH:-/opt/ITM/IIM/zabbix_agentd}\"\nCONF=\"$INSTALL_PATH/etc/zabbix_agentd.conf\"\nif [ ! -f \"$CONF\" ]; then echo \"未找到 $CONF\" >&2; exit 1; fi\npkill -f \"$CONF\" 2>/dev/null || true\necho stopped\n'
WHERE name = 'Zabbix Agent 停止';
